		end: () => true,
		on: () => stub,
		once: () => stub,
		emit: () => true,
		removeListener: () => stub,
		addListener: () => stub,
		setDefaultEncoding: () => stub,
		cork: () => void 0,
		uncork: () => void 0,
		destroy: () => stub,
