/**
* `\sv <name>` — show view definition.
*/
const describeOneViewDetails = async (conn, oid, schema, name, out, popt, verbose = false, hideCompression = false) => {
	await describeOneTableDetails(conn, oid, schema, name, "v", verbose, out, popt, false, hideCompression);
};
/**
* Translate a relkind char into the canonical header psql uses for
* `\d <name>`. Examples: 'r' → `Table "schema.name"`; 'v' → `View "..."`.
*/
const headerForRelkind = (relkind, schema, name) => {
	switch (relkind) {
		case "r": return `Table "${schema}.${name}"`;
		case "v": return `View "${schema}.${name}"`;
		case "m": return `Materialized view "${schema}.${name}"`;
		case "S": return `Sequence "${schema}.${name}"`;
		case "i": return `Index "${schema}.${name}"`;
		case "I": return `Partitioned index "${schema}.${name}"`;
		case "p": return `Partitioned table "${schema}.${name}"`;
		case "f": return `Foreign table "${schema}.${name}"`;
		case "t": return `TOAST table "${schema}.${name}"`;
		case "c": return `Composite type "${schema}.${name}"`;
		default: return `Relation "${schema}.${name}"`;
	}
};
/**
* Build a minimal {@link FieldDescription} for synthesized rows where
* we don't actually have a wire-level row description. Used by the
* columns table in `describeOneTableDetails` because we synthesize
* the layout from pg_attribute data.
*/
const fakeField = (name) => ({
	name,
	tableID: 0,
	columnID: 0,
	dataTypeID: 25,
	dataTypeSize: -1,
	dataTypeModifier: -1,
	format: 0
});
